with oracledb.connect(user=s.oracle_user,password=s.oracle_password,dsn=s.oracle_dsn)as c:
 q=c.cursor();q.execute("select t.WARE_ID,t.PICK_WAVE_ID,n.SITE_CODE,count(*) from RRL_CASE_PICK_TASK t join RRL_CASE_PICK_LINE l on l.CASE_PICK_TASK_ID=t.CASE_PICK_TASK_ID join RRL_PICK_WAVE w on w.PICK_WAVE_ID=t.PICK_WAVE_ID join RRL_WORKLOAD_NORM n on n.WARE_ID=t.WARE_ID and n.ARTICLE=l.ARTICUL and n.ACTIVE=1 where t.STATUS in('NEW','ASSIGNED','IN_PROGRESS','PARTIAL','WAIT_REPLENISHMENT')and l.STATUS not in('DONE','CANCELLED')and l.PLANNED_QTY>l.PICKED_QTY and w.STATUS not in('DONE','CANCELLED') group by t.WARE_ID,t.PICK_WAVE_ID,n.SITE_CODE fetch first 8 rows only");print(json.dumps(q.fetchall()))